@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Bench.Umbraco.Models.Blocks
@inherits UmbracoViewPage<BlockGridItem<RichTextBlock>>
@{
    var model = new RichTextModel
    {
        Html = Model.Content.Text?.ToHtmlString() ?? "",
    };
}
@await Component.InvokeAsync("RichText", new { model })

@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Bench.Umbraco.Models.Blocks
@inherits UmbracoViewPage<BlockGridItem<ImageBlock>>
@{
    var model = new ImageModel
    {
        ImageUrl = Model.Content.Image?.GetCropUrl(width: 1200),
        Caption = Model.Content.Caption,
    };
}
@await Component.InvokeAsync("Image", new { model })

@using Umbraco.Cms.Core.Models.Blocks
@using Umbraco.Bench.Umbraco.Models
@using Umbraco.Bench.Umbraco.Models.Blocks
@inherits UmbracoViewPage<BlockGridItem<QuoteBlock>>
@{
    var model = new QuoteModel
    {
        Quote = Model.Content.Quote,
        Attribution = Model.Content.Attribution,
    };
}
@await Component.InvokeAsync("Quote", new { model })

@model Umbraco.Bench.Umbraco.Models.Blocks.ImageModel

<figure class="my-8">
    @if (!string.IsNullOrWhiteSpace(Model.ImageUrl))
    {
        <img src="@Model.ImageUrl" alt="@Model.Caption" class="w-full rounded-lg" />
    }
    @if (!string.IsNullOrWhiteSpace(Model.Caption))
    {
        <figcaption class="mt-2 text-sm text-gray-500">@Model.Caption</figcaption>
    }
</figure>

@model Umbraco.Bench.Umbraco.Models.Blocks.QuoteModel

<blockquote class="my-8 border-l-4 border-indigo-500 pl-6 text-xl italic text-gray-700">
    <p>“@Model.Quote”</p>
    @if (!string.IsNullOrWhiteSpace(Model.Attribution))
    {
        <cite class="mt-2 block text-sm not-italic text-gray-500">@Model.Attribution</cite>
    }
</blockquote>

