@using Umbraco.Bench.Umbraco.Models
@inherits UmbracoViewPage<BlogPost>
@{
    Layout = null;
}
<!doctype html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>@Model.Title</title>
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="bg-gray-50 text-gray-900">
    <main class="mx-auto max-w-3xl px-6 py-10">
        <p class="text-sm text-gray-500">@Model.PublishDate.ToString("d MMMM yyyy")</p>
        <h1 class="mt-2 text-4xl font-bold tracking-tight">@Model.Title</h1>
        @if (!string.IsNullOrWhiteSpace(Model.Excerpt))
        {
            <p class="mt-4 text-lg text-gray-600">@Model.Excerpt</p>
        }
        @await Html.GetBlockGridHtmlAsync(Model, "body")
        <p class="mt-12">
            <a href="@Model.Parent?.Url()" class="text-indigo-600 hover:underline">← Back to the blog</a>
        </p>
    </main>
</body>
</html>

